import './style.css';
import {createIcons,Sun,Check,Plus,ChevronLeft,ChevronRight,CalendarDays,LayoutDashboard,Layers,BookOpen,LibraryBig,Dumbbell,Coffee,ShowerHead,Droplets,Footprints,Heart,Moon,Flower2,BriefcaseBusiness,GraduationCap,Languages,House,Music,NotebookPen,Leaf,Settings,LogOut,ArrowUpRight,ArrowRight,MoreHorizontal,CheckCheck,Clock,Play,Pause,Square,Search,X,Trash2,Download,Cloud,CloudOff,RefreshCw,ChartNoAxesColumn,Target,Flag,RotateCcw,Mail,Lock,User,CheckCircle2,Menu,Sparkles} from 'lucide';
import {AREAS,ICONS,PALETTE,uid,dayKey,parseDay,addDays,scheduled,occurs,dayStats,streak,elapsed,fmtDuration,weekKeys,eventOnDate} from './domain.js';
import * as db from './store.js';
import { daySummary, dayWelcome } from './daily.js';
import { initCatalog, closeCatalog, catalog, catalogBook, isCatalogId, recordProgress, refreshCatalog } from './library-bridge.js';
import { wellbeingView, wellbeingAction } from './wellbeing.js';
import {planningView,planningAction,effectiveDayMode} from './planning.js';
import {extrasView,extrasAction} from './extras.js';
import {notificationsView,notificationsAction} from './notifications.js';
const icons={Sun,Check,Plus,ChevronLeft,ChevronRight,CalendarDays,LayoutDashboard,Layers,BookOpen,LibraryBig,Dumbbell,Coffee,ShowerHead,Droplets,Footprints,Heart,Moon,Flower2,BriefcaseBusiness,GraduationCap,Languages,House,Music,NotebookPen,Leaf,Settings,LogOut,ArrowUpRight,ArrowRight,MoreHorizontal,CheckCheck,Clock,Play,Pause,Square,Search,X,Trash2,Download,Cloud,CloudOff,RefreshCw,ChartNoAxesColumn,Target,Flag,RotateCcw,Mail,Lock,User,CheckCircle2,Menu,Sparkles};
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<i data-lucide="${(icons[name]?name:'Leaf').replace(/([a-z0-9])([A-Z])/g,'$1-$2').toLowerCase()}" class="${cls}"></i>`;
let user=null,view='today',areaFilter='',date=dayKey(),month=date.slice(0,7),tab='diario',search='',authMode='login',recovery=false,ready=false,toastTimer;
const rec=kind=>db.records(kind),settings=()=>rec('settings')[0]||{},get=(kind,id)=>rec(kind).find(r=>r.id===id),areas=()=>rec('area'),area=id=>areas().find(a=>a.id===id)||AREAS[0];
const btn=(text,action,extra='',cls='button')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const prettyDate=(key,opts={weekday:'long',day:'numeric',month:'long'})=>parseDay(key).toLocaleDateString('es-PY',opts);
const time=t=>new Date(t).toLocaleTimeString('es-PY',{hour:'2-digit',minute:'2-digit'});
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4200);}
function paintIcons(){createIcons({icons,attrs:{'stroke-width':1.65}});}
function greeting(){return dayWelcome().greeting;}
const readingTitle=r=>catalogBook(r.bookId)?.titulo||r.bookTitle||get('book',r.bookId)?.title||'Lectura libre';
function renderAuth(){app.innerHTML=`<main class="auth-page"><section class="auth-story"><a class="brand" href="./"><span class="brand-mark">${icon('Check')}</span>habits<span class="brand-dot">.</span></a><div><p class="eyebrow">UN ESPACIO PARA VOS</p><h1>Los pequeños pasos<br>hacen grandes<br><em>días.</em></h1><p>Tu rutina, tus libros, tus planes.<br>Todo lo que te hace bien, en un mismo lugar.</p><div class="auth-chips"><span>${icon('Sun')} Tu día</span><span>${icon('BookOpen')} Tu tiempo</span><span>${icon('Heart')} Tu ritmo</span></div></div><small>Organizá tu día. Celebrá lo que sí hiciste.</small></section><section class="auth-form-wrap"><div class="auth-form"><span class="mini-icon">${icon(recovery?'Lock':'Leaf')}</span><p class="eyebrow">BIENVENIDA A HABITS</p><h2>${recovery?'Una nueva contraseña':authMode==='signup'?'Hacé espacio para vos':authMode==='reset'?'Recuperá tu cuenta':'Qué lindo verte por acá'}</h2><p class="muted">${recovery?'Elegí una contraseña de al menos 8 caracteres.':authMode==='signup'?'Creá tu cuenta y empezá a tu ritmo.':authMode==='reset'?'Te enviaremos un enlace para cambiar tu contraseña.':'Entrá a tu espacio personal.'}</p><form id="auth-form">${authMode==='signup'&&!recovery?'<label>Tu nombre<input name="name" autocomplete="given-name" required maxlength="60" placeholder="¿Cómo te llamás?"></label>':''}${!recovery?'<label>Correo electrónico<input type="email" name="email" autocomplete="email" required placeholder="vos@ejemplo.com"></label>':''}${authMode!=='reset'||recovery?'<label>Contraseña<input type="password" name="password" autocomplete="'+(authMode==='signup'||recovery?'new-password':'current-password')+'" minlength="8" required placeholder="Al menos 8 caracteres"></label>':''}<p id="auth-error" role="alert"></p><button class="button primary wide" ${!db.configured?'disabled':''}>${recovery?'Guardar contraseña':authMode==='signup'?'Crear mi cuenta':authMode==='reset'?'Enviar enlace':'Entrar a mi día'} ${icon('ArrowRight')}</button></form>${!recovery?`<div class="auth-links">${btn(authMode==='signup'?'Ya tengo cuenta':'Crear una cuenta',authMode==='signup'?'login':'signup','','text-button')}${btn('Olvidé mi contraseña','reset','','text-button')}</div>`:''}${!db.configured?'<div class="notice">El registro estará disponible cuando conectemos Supabase. Mientras tanto, podés explorar la app en este dispositivo.</div>':''}${!recovery?btn('Explorar la demo '+icon('ArrowUpRight'),'demo','','button outline wide'):''}<small class="muted auth-foot">La demo guarda datos solo en este navegador.<br>Tu cuenta sincronizará iPhone y notebook.</small></div></section></main>`;paintIcons();document.querySelector('#auth-form').onsubmit=submitAuth;}
async function submitAuth(e){e.preventDefault();const f=new FormData(e.target),b=e.target.querySelector('button');b.disabled=true;const errorEl=document.querySelector('#auth-error');errorEl.textContent='';try{let res;const redirect=location.origin+location.pathname;if(recovery)res=await db.supabase.auth.updateUser({password:f.get('password')});else if(authMode==='signup')res=await db.supabase.auth.signUp({email:f.get('email'),password:f.get('password'),options:{data:{name:f.get('name')},emailRedirectTo:redirect}});else if(authMode==='reset')res=await db.supabase.auth.resetPasswordForEmail(f.get('email'),{redirectTo:redirect});else res=await db.supabase.auth.signInWithPassword({email:f.get('email'),password:f.get('password')});if(res.error)throw res.error;if(recovery){recovery=false;toast('Contraseña actualizada.');render();}else if(authMode==='reset')errorEl.textContent='Si existe una cuenta con ese correo, recibirás un enlace. Revisá también spam.';else if(authMode==='signup'&&!res.data.session)errorEl.textContent='Revisá tu correo para confirmar tu cuenta antes de entrar.';}catch(err){errorEl.textContent=err.message==='Invalid login credentials'?'El correo o la contraseña no coinciden.':err.message==='Email not confirmed'?'Confirmá tu correo antes de entrar.':'No se pudo completar la solicitud. '+err.message;}finally{b.disabled=false;}}
async function enter(u){if(user?.id===u.id&&ready)return;db.closeStore();closeCatalog();user=u;ready=true;await db.openStore(u.id,render);initCatalog(u.id,render);if(!settings().name&&u.user_metadata?.name)db.put('settings',{...settings(),name:u.user_metadata.name},'settings');render();}
function syncLabel(){const s=db.info();if(s.demo)return 'Demo · solo en este equipo';return ({loading:'Cargando tu espacio…',syncing:'Sincronizando…',offline:'Sin conexión · guardado aquí',error:'Pendiente · reintentar',conflict:'Revisar cambios',pending:'Cambios pendientes',synced:'Todo sincronizado'})[s.status];}
function render(){if(recovery||!user){renderAuth();return;}const s=settings();document.documentElement.dataset.theme=s.theme||'light';document.documentElement.classList.toggle('large',!!s.large);document.documentElement.classList.toggle('quiet',!!s.quiet);const nav=[['today','LayoutDashboard','Mi día'],['calendar','CalendarDays','Calendario'],['areas','Layers','Mis áreas'],['space','Flower2','Mi espacio'],['diary','NotebookPen','Mi diario']];app.innerHTML=`<div class="app-layout"><aside class="sidebar"><a class="brand" href="#" data-action="nav" data-view="today"><span class="brand-mark">${icon('Check')}</span>habits<span class="brand-dot">.</span></a><p class="sidebar-label">TU ESPACIO PERSONAL</p><nav>${nav.map(([id,ic,label])=>btn(icon(ic)+`<span>${label}</span>${id===view?'<span class="nav-dot"></span>':''}`,'nav',`data-view="${id}"`,view===id?'nav-link active':'nav-link')).join('')}</nav><div class="sidebar-areas"><p class="sidebar-label">TUS ÁREAS ${btn(icon('Plus'),'new-area','aria-label="Crear área"','icon-button')}</p>${areas().slice(0,7).map(a=>btn(`<span class="area-dot" style="background:${safeColor(a.color)}"></span>${esc(a.name)}`,'area',`data-id="${esc(a.id)}"`,'area-link')).join('')}</div><div class="sidebar-quote">${icon('Flower2')}<p>No hace falta hacerlo todo.<br><em>Hacé lugar para lo que importa.</em></p></div>${btn(icon('Settings')+'Ajustes','settings','','nav-link')}</aside><div class="main-wrap"><header class="topbar"><div class="breadcrumb">Mi espacio <span>/</span> <strong>${nav.find(n=>n[0]===view)?.[2]||'Mi día'}</strong></div><button class="sync-pill" data-action="sync" title="Reintentar sincronización">${icon(db.info().status==='offline'?'CloudOff':'Cloud')}<span>${syncLabel()}</span></button>${btn(icon('Search'),'search','aria-label="Buscar"','icon-button')}${btn(`<span class="avatar">${esc((s.name||user.user_metadata?.name||'V').slice(0,1).toUpperCase())}</span>`,'settings','aria-label="Abrir perfil y ajustes"','profile-button')}</header><main class="content">${db.info().conflicts.length?`<div class="notice">Hay cambios del otro dispositivo para revisar. ${btn('Revisar','conflicts','','text-button')}</div>`:''}${view==='today'?todayView():view==='calendar'?calendarView():view==='areas'?areasView():view==='diary'?journalView():spaceView()}</main><footer class="page-footer">A tu ritmo, un día a la vez. <span>Hecho para tus pequeños grandes logros ${icon('Leaf')}</span></footer></div><nav class="mobile-nav">${nav.map(([id,ic,label])=>btn(icon(ic)+`<span>${label}</span>`,'nav',`data-view="${id}"`,view===id?'active':'')).join('')}</nav></div>`;paintIcons();tick();}
function safeColor(c){return /^#[0-9a-f]{6}$/i.test(c)?c:'#738d70';}
function heading(kicker,title,subtitle,actions=''){return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1>${subtitle?`<p class="muted">${subtitle}</p>`:''}</div><div class="heading-actions">${actions}</div></div>`;}
function empty(text,action='',label='Agregar'){return `<div class="empty">${icon('Leaf')}<p>${text}</p>${action?btn(icon('Plus')+label,action,'','button outline'):''}</div>`;}
function todayView(){const today=dayKey(),hs=rec('habit').sort((a,b)=>(a.order||0)-(b.order||0)),logs=rec('log'),stats=dayStats(hs,logs,today),name=settings().name||user.user_metadata?.name||'';const done=hs.filter(h=>logs.some(l=>l.habitId===h.id&&l.date===today&&l.status==='done'));const summary=daySummary({habits:hs,logs,events:rec('event'),eventLogs:rec('eventLog'),readings:rec('reading'),journals:rec('journal'),finishedBooks:catalog().finishedToday},today);const upcoming=rec('event').filter(e=>occurs(e,today)).sort((a,b)=>(a.time||'').localeCompare(b.time||''));const completedLogs=logs.filter(l=>l.date===today&&l.status==='done');const reads=rec('reading').filter(r=>r.date===today);const dayMode=effectiveDayMode(settings());const shown=hs.filter(h=>scheduled(h,today)&&(dayMode==='tranquilo'?h.essential:true));return `${heading(`<span data-date>${prettyDate(today)}</span> <span class="date-divider">/</span> <span data-clock></span>`,`${greeting()}${name?', '+esc(name):''}<span class="sun-glyph">${icon(dayWelcome().icon)}</span>`,dayWelcome().subtitle,btn(icon('Plus')+'Crear','create','','button primary'))}<section class="day-hero"><div><p class="eyebrow">TU DÍA, A TU RITMO</p><h2>${done.length?'Mirá todo lo que ya hiciste.':'Un nuevo día.<br>Un poquito más para vos.'}</h2><p>${esc(summary)}</p><div class="hero-bottom"><span class="warm-note">${icon('Sparkles')}${done.length?'¡Bien por vos! Cada paso suma.':'Sin apuro. Lo importante es empezar.'}</span>${btn('Ver mi progreso '+icon('ArrowUpRight'),'progress','','text-button')}</div></div><div class="progress-ring" style="--progress:${stats.percent*3.6}deg"><div><strong>${stats.done}<small> / ${stats.total}</small></strong><span>hábitos completos</span><b>${stats.percent}% de tu día</b></div></div></section><div class="dashboard-grid"><div class="left-column"><section><div class="section-title"><div><h2>Mis hábitos de hoy <span class="count">${shown.length}</span></h2><p>Pequeñas acciones que te hacen bien.</p></div>${btn(icon('Plus')+'Nuevo hábito','new-habit','','text-button')}</div><div class="filter-bar"><div class="chips">${['Todos','mañana','tarde','noche'].map(p=>btn(p==='Todos'?'Todo el día':p[0].toUpperCase()+p.slice(1),'period',`data-period="${p}"`,(window.periodFilter||'Todos')===p?'chip selected':'chip')).join('')}</div><select id="day-mode" aria-label="Tipo de día"><option value="habitual" ${dayMode==='habitual'?'selected':''}>Día habitual</option><option value="tranquilo" ${dayMode==='tranquilo'?'selected':''}>Día tranquilo</option>${[["trabajo","Día de trabajo"],["facultad","Día de facu"],["finDeSemana","Fin de semana"]].map(([k,n])=>`<option value="${k}" ${dayMode===k?'selected':''}>${n}</option>`).join('')}<option value="descanso" ${dayMode==='descanso'?'selected':''}>Día de descanso</option></select></div>${dayMode==='descanso'?'<div class="notice">Hoy podés ir más despacio. Usá “Hoy no” en los hábitos que quieras pausar.</div>':''}<div class="habit-grid">${shown.filter(h=>!window.periodFilter||window.periodFilter==='Todos'||h.period===window.periodFilter).map(h=>habitCard(h,today)).join('')||empty('Tu rutina puede empezar con una pequeña acción.','new-habit','Crear un hábito')}</div></section><section class="timeline-section"><div class="section-title"><div><h2>Así va tu día</h2><p>Lo que hiciste merece su lugar.</p></div>${btn(icon('Plus')+'También hice esto','achievement','','text-button')}</div><div class="timeline">${[...completedLogs.map(l=>({at:l.at,title:get('habit',l.habitId)?.name||'Hábito completado',detail:l.note||'Un paso más para vos',icon:get('habit',l.habitId)?.icon||'Check'})),...reads.map(r=>({at:r.at,title:'Tiempo de lectura',detail:`${r.minutes} min · ${readingTitle(r)}`,icon:'BookOpen'})),...rec('eventLog').filter(e=>e.date===today).map(e=>({at:e.at,title:get('event',e.eventId)?.name||'Evento realizado',detail:'Evento completado',icon:'CalendarDays'})),...rec('journal').filter(j=>j.date===today&&j.achievement).map(j=>({at:j.at,title:j.text,detail:'Un logro que también cuenta',icon:'Sparkles'}))].sort((a,b)=>a.at.localeCompare(b.at)).map(e=>`<div class="timeline-item"><span>${time(e.at)}</span><b class="timeline-dot">${icon(e.icon)}</b><div><strong>${esc(e.title)}</strong><p>${esc(e.detail)}</p></div></div>`).join('')||'<p class="muted timeline-empty">Cuando completes una actividad, aparecerá acá. Tu día todavía tiene mucho por contar.</p>'}</div></section></div><aside class="right-column">${extrasView({btn})}${wellbeingView({esc,btn})}<section class="panel agenda-panel"><div class="section-title"><h2>En tu agenda</h2>${btn(icon('ArrowUpRight'),'nav','data-view="calendar" aria-label="Ver calendario"','icon-button')}</div><div class="mini-week">${weekKeys(today).map(d=>`<button data-action="date" data-date="${d}" class="${d===today?'today':''}"><span>${prettyDate(d,{weekday:'short'}).slice(0,3)}</span><b>${parseDay(d).getDate()}</b><i class="${rec('event').some(e=>occurs(e,d))?'has-event':''}"></i></button>`).join('')}</div><div class="agenda-list">${upcoming.length?upcoming.slice(0,4).map(e=>eventCard(e,today)).join(''):'<div class="small-empty">Un poco de espacio libre.<br>¿Qué te gustaría hacer hoy?</div>'}</div>${btn(icon('Plus')+'Agregar un evento','new-event','','button outline wide')}</section><section class="panel reading-panel"><p class="eyebrow">TU RINCÓN DE LECTURA ${icon('BookOpen')}</p>${readingWidget()}</section><section class="reflection-card"><span>${icon('Heart')}</span><h3>¿Cómo te sentís hoy?</h3><p>Tomate un momento para escucharte.</p><div class="moods">${['😔','😐','🙂','😊','🤩'].map((m,i)=>btn(m,'mood',`data-mood="${i+1}" aria-label="Ánimo ${i+1} de 5"`,rec('journal').some(j=>j.date===today&&!j.achievement&&!j.workoutPhoto&&!j.englishPractice&&j.mood===i+1)?'chosen':'')).join('')}</div></section></aside></div>`;}
function habitCard(h,d){const l=rec('log').find(x=>x.habitId===h.id&&x.date===d),a=area(h.area),done=l?.status==='done',skip=l?.status==='skip';return `<article draggable="true" data-habit-id="${h.id}" class="habit-card ${done?'done':''} ${skip?'skipped':''}" style="--area:${safeColor(h.color||a.color)}"><div class="habit-top"><span class="habit-icon">${icon(h.icon)}</span>${btn(icon('MoreHorizontal'),'edit-habit',`data-id="${h.id}" aria-label="Editar ${esc(h.name)}"`,'icon-button')}</div><span class="habit-area">${esc(a.name)}</span><h3>${esc(h.name)}</h3><p>${h.type==='check'?`${icon('Sun')}${esc(h.period)}`:`${icon(h.type==='time'?'Clock':'Target')}${l?.value||0} / ${h.target} ${esc(h.unit)}`}</p><div class="habit-bottom">${btn(icon(done?'CheckCheck':skip?'RotateCcw':h.type==='check'?'Check':'Plus')+(done?'Hecho':skip?'Retomar':h.type==='check'?'Marcar hecho':'Registrar'),'habit-action',`data-id="${h.id}" data-date="${d}"`,'habit-check')}${done?`<span class="done-time">${time(l.at)}</span>`:btn('Hoy no','skip',`data-id="${h.id}" data-date="${d}"`,'text-button small')}</div></article>`;}
function eventCard(e,d){e=eventOnDate(e,d);const a=area(e.area),done=rec('eventLog').some(l=>l.eventId===e.id&&l.date===d);return `<article class="event-card" style="--area:${safeColor(a.color)}"><div><span class="event-time">${e.time||'Todo el día'}${e.end?' – '+e.end:''}</span><button class="event-title" data-action="event-options" data-date="${d}" data-id="${e.id}">${esc(e.name)}</button><small>${esc(a.name)}${e.location?' · '+esc(e.location):''}</small></div>${btn(icon(done?'CheckCheck':'Check'),'event-done',`data-id="${e.id}" data-date="${d}" aria-label="${done?'Desmarcar':'Completar'} evento"`,'icon-button '+(done?'checked':''))}</article>`;}
function currentReading(){const c=catalog();if(c.allowed){const b=c.reading[0];return b?{id:'lib:'+b.id,title:b.titulo,author:b.autor,page:b.pagina_actual||0,pages:b.paginas,more:c.reading.length-1}:null;}const b=rec('book').find(b=>b.status==='reading');return b?{id:b.id,title:b.title,author:b.author,page:b.page||0,pages:b.pages,more:0}:null;}
function readingWidget(){const c=catalog(),book=currentReading(),timer=get('timer','reading-timer');const link=c.allowed?`<a class="text-button reading-link" href="./biblioteca.html">Ir a mi biblioteca ${icon('ArrowRight')}</a>`:`<button class="text-button reading-link" data-action="library">Ir a mi biblioteca ${icon('ArrowRight')}</button>`;return `<h3>${book?esc(book.title):'Una página, un nuevo mundo.'}</h3><p>${book?esc(book.author||'Tu lectura actual'):c.allowed?'Cuando empieces un libro en tu biblioteca, va a aparecer acá.':'Guardá tus libros y disfrutá de un ratito de lectura.'}</p>${book?`<div class="book-progress"><span>Página ${book.page} de ${book.pages||'—'}${book.more>0?` · y ${book.more} ${book.more===1?'libro más':'libros más'}`:''}</span><progress value="${book.page}" max="${book.pages||100}"></progress></div>`:''}${timer?`<div class="timer-display" data-timer>${fmtDuration(elapsed(timer))}</div><div class="button-row">${btn(icon(timer.running?'Pause':'Play')+(timer.running?'Pausar':'Seguir'),'timer-toggle','','button outline')}${btn(icon('Square')+'Terminar','timer-stop','','button primary')}</div>`:btn(icon('Play')+'Mi momento de lectura','timer-start','','button outline wide')}${link}`;}
function calendarView(){if(window.calendarMode==='week')return `${heading('TU SEMANA','Tu calendario','Una vista de tus horarios.',btn('Ver mes','calendar-mode','data-mode="month"','button outline'))}<div class="button-row">${btn('Semana anterior','week-step','data-step="-7"','button outline')}${btn('Hoy','calendar-today','','button outline')}${btn('Semana siguiente','week-step','data-step="7"','button outline')}${btn('Agregar evento','new-event','','button primary')}</div><div class="week-agenda">${weekKeys(date).map(d=>`<section><h3>${prettyDate(d,{weekday:'short',day:'numeric',month:'short'})}</h3>${rec('event').filter(e=>occurs(e,d)).map(e=>eventOnDate(e,d)).sort((a,b)=>(a.time||'').localeCompare(b.time||'')).map(e=>eventCard(e,d)).join('')||'<p class="muted">Sin eventos</p>'}</section>`).join('')}</div>`;const first=parseDay(month+'-01'),offset=(first.getDay()+6)%7,gridStart=addDays(dayKey(first),-offset),selected=rec('event').filter(e=>occurs(e,date)).sort((a,b)=>(a.time||'').localeCompare(b.time||''));return `${heading('HACÉ ESPACIO PARA TUS PLANES','Tu calendario','Tus compromisos y tus momentos, en equilibrio.',btn(icon('Plus')+'Nuevo evento','new-event','','button primary'))}<div class="calendar-layout"><section class="panel calendar-panel"><div class="calendar-toolbar">${btn('Ver semana','calendar-mode','data-mode="week"','button outline')}<h2>${first.toLocaleDateString('es-PY',{month:'long',year:'numeric'})}</h2><div class="button-row">${btn('Hoy','calendar-today','','button outline')}${btn(icon('ChevronLeft'),'month','data-step="-1" aria-label="Mes anterior"','icon-button')}${btn(icon('ChevronRight'),'month','data-step="1" aria-label="Mes siguiente"','icon-button')}</div></div><div class="calendar-grid">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(d=>`<div class="weekday">${d}</div>`).join('')}${Array.from({length:42},(_,i)=>{const d=addDays(gridStart,i),ev=rec('event').filter(e=>occurs(e,d)),st=dayStats(rec('habit'),rec('log'),d);return `<button class="calendar-cell ${d.slice(0,7)!==month?'outside':''} ${d===date?'selected':''} ${d===dayKey()?'current':''}" data-action="date" data-date="${d}"><span>${parseDay(d).getDate()}</span><div class="calendar-events">${ev.slice(0,2).map(e=>`<small style="--area:${safeColor(area(e.area).color)}">${esc(e.name)}</small>`).join('')}${ev.length>2?`<small>+${ev.length-2} más</small>`:''}</div>${st.done?`<b class="calendar-progress">${st.done} ✓</b>`:''}</button>`;}).join('')}</div></section><aside><section class="panel"><p class="eyebrow">${prettyDate(date,{weekday:'long'})}</p><h2>${prettyDate(date,{day:'numeric',month:'long'})}</h2><div class="agenda-list">${selected.map(e=>eventCard(e,date)).join('')||empty('Este día todavía no tiene eventos.')}</div>${btn(icon('Plus')+'Agregar evento','new-event','','button outline wide')}</section><section class="panel day-history"><h3>Hábitos de este día</h3>${rec('habit').filter(h=>scheduled(h,date)).map(h=>{const l=rec('log').find(l=>l.habitId===h.id&&l.date===date);return `<button class="history-row" data-action="habit-action" data-id="${h.id}" data-date="${date}">${icon(l?.status==='done'?'CheckCircle2':h.icon)}<span>${esc(h.name)}</span><small>${l?.status==='done'?'Hecho':l?.status==='skip'?'Pausa':'Pendiente'}</small></button>`;}).join('')||'<p class="muted">No hay hábitos programados.</p>'}</section></aside></div>`;}
function areasView(){const a=areaFilter?area(areaFilter):null;return `${heading('LO QUE IMPORTA EN TU VIDA',a?esc(a.name):'Mis áreas','Un lugar para cada parte de vos.',btn(icon('Plus')+'Nueva área','new-area','','button primary'))}<div class="chips area-filters">${btn('Todas','area','data-id=""',!a?'chip selected':'chip')}${areas().map(x=>btn(icon(x.icon)+esc(x.name),'area',`data-id="${x.id}"`,x.id===areaFilter?'chip selected':'chip')).join('')}</div>${!a?`<div class="areas-grid">${areas().map(x=>`<button class="area-tile" style="--area:${safeColor(x.color)}" data-action="area" data-id="${x.id}"><span class="habit-icon">${icon(x.icon)}</span><h2>${esc(x.name)}</h2><p>${rec('habit').filter(h=>h.area===x.id&&!h.archived).length} hábitos · ${rec('task').filter(t=>t.area===x.id&&!t.done).length} pendientes</p>${icon('ArrowUpRight')}</button>`).join('')}</div>`:`<div class="button-row area-tools">${btn(icon('Plus')+'Hábito','new-habit','','button outline')}${btn(icon('Plus')+'Tarea','new-task','','button outline')}${btn(icon('Settings')+'Editar área','edit-area',`data-id="${a.id}"`,'button outline')}</div>${a.id==='lectura'?libraryView():a.id==='ingles'?vocabView():''}<div class="section-title"><h2>Hábitos de ${esc(a.name)}</h2></div><div class="habit-grid">${rec('habit').filter(h=>h.area===a.id&&!h.archived).map(h=>habitCard(h,dayKey())).join('')||empty('Agregá tu primer hábito para esta área.','new-habit')}</div><div class="section-title"><h2>Pendientes</h2></div>${taskList(rec('task').filter(t=>t.area===a.id))}`}`;}
function spaceView(){const tabs=[['diario','Mi diario'],['tareas','Pendientes'],['biblioteca','Biblioteca'],['proyectos','Proyectos'],['planning','Estudio y trabajo'],['progreso','Mi progreso']];return `${heading('TU HISTORIA, PASO A PASO','Mi espacio','Ideas, lecturas y logros que querés guardar.')}<div class="chips space-tabs">${tabs.map(([id,name])=>btn(name,'space-tab',`data-tab="${id}"`,tab===id?'chip selected':'chip')).join('')}</div>${tab==='planning'?planningView({esc,btn}):tab==='biblioteca'?libraryView():tab==='progreso'?progressView():tab==='tareas'?`<div class="section-title"><h2>Una cosa a la vez</h2>${btn(icon('Plus')+'Nueva tarea','new-task','','button primary')}</div>${taskList(rec('task'))}`:tab==='proyectos'?projectsView():journalView()}`;}
function taskList(tasks){return `<div class="task-list">${tasks.sort((a,b)=>Number(a.done)-Number(b.done)||(a.due||'9999').localeCompare(b.due||'9999')).map(t=>`<article class="task-row ${t.done?'completed':''}">${btn(icon(t.done?'CheckCircle2':'Check'),'task-done',`data-id="${t.id}" aria-label="${t.done?'Reabrir':'Completar'} tarea"`,'icon-button')}<button class="task-main" data-action="edit-task" data-id="${t.id}"><strong>${esc(t.name)}</strong><small>${esc(area(t.area).name)} ${t.projectId?' · '+esc(get('project',t.projectId)?.name||''):''}${t.due?' · '+prettyDate(t.due,{day:'numeric',month:'short'}):' · Para después'}</small></button><span class="priority ${t.priority==='alta'?'high':''}">${t.priority==='alta'?'Alta':t.priority==='baja'?'Baja':'Media'}</span>${t.due<dayKey()&&!t.done?'<span class="overdue">Vencida</span>':''}</article>`).join('')||empty('Lo pendiente puede empezar con una pequeña tarea.','new-task','Crear tarea')}</div>`;}
function catalogReadingCards(){const c=catalog();return c.reading.map(b=>`<article class="book-card"><a class="book-cover" href="./biblioteca.html"><span>${icon('BookOpen')}</span><h3>${esc(b.titulo)}</h3><small>${esc(b.autor||'')}</small></a><div class="book-details"><span class="tag">${b.estado_lectura==='releyendo'?'Releyendo':'Leyendo'}</span><h3>${esc(b.titulo)}</h3><p>${esc(b.autor||'Sin autor registrado')}</p><progress max="${b.paginas||100}" value="${b.pagina_actual||0}"></progress><small>${b.pagina_actual||0} / ${b.paginas||'—'} páginas</small></div></article>`).join('')||empty('Cuando empieces un libro en tu biblioteca, va a aparecer acá.');}
function libraryView(){const c=catalog();return `<div class="section-title"><div><h2>Entre páginas</h2><p>${c.allowed?'Lo que estás leyendo ahora en tu biblioteca.':'Historias que te acompañan.'}</p></div>${c.allowed?'<a class="button primary" href="./biblioteca.html">Abrir mi biblioteca</a>':btn(icon('Plus')+'Agregar libro','new-book','','button primary')}</div><div class="library-layout"><div class="books-grid">${c.allowed?catalogReadingCards():rec('book').map(b=>`<article class="book-card"><button class="book-cover" style="--book:${safeColor(b.color)}" data-action="edit-book" data-id="${b.id}"><span>${icon('BookOpen')}</span><h3>${esc(b.title)}</h3><small>${esc(b.author)}</small></button><div class="book-details"><span class="tag">${({reading:'Leyendo',pending:'Por leer',finished:'Terminado',paused:'En pausa'})[b.status]}</span><h3>${esc(b.title)}</h3><p>${esc(b.author||'Sin autor registrado')}</p><progress max="${b.pages||100}" value="${b.page||0}"></progress><small>${b.page||0} / ${b.pages||'—'} páginas</small>${btn('Actualizar lectura '+icon('ArrowRight'),'edit-book',`data-id="${b.id}"`,'text-button')}</div></article>`).join('')||empty('Tu próximo libro favorito merece un lugar acá.','new-book','Agregar libro')}</div><aside class="panel reading-panel">${readingWidget()}<hr><h3>Sesiones recientes</h3>${rec('reading').sort((a,b)=>b.at.localeCompare(a.at)).slice(0,5).map(r=>`<p class="session-row"><span>${esc(readingTitle(r))}<small>${prettyDate(r.date,{day:'numeric',month:'short'})}</small></span><b>${r.minutes} min</b></p>`).join('')||'<p class="muted">Un momento de lectura también es un logro.</p>'}${btn('Registrar minutos manualmente','manual-reading','','text-button')}</aside></div><div class="section-title"><h2>Palabras para guardar</h2>${btn(icon('Plus')+'Guardar cita','new-quote','','text-button')}</div><div class="quotes-grid">${rec('quote').map(q=>`<button class="quote-card" data-action="edit-quote" data-id="${q.id}"><blockquote>“${esc(q.text)}”</blockquote><small>${esc(catalogBook(q.bookId)?.titulo||q.bookTitle||get('book',q.bookId)?.title||q.author||'Mi cita favorita')}${q.page?' · p. '+q.page:''}</small></button>`).join('')||'<p class="muted">Guardá acá las frases que te hacen detenerte un momento.</p>'}</div>`;}
function vocabView(){return `<section class="panel"><div class="section-title"><h2>Mi vocabulario</h2>${btn(icon('Plus')+'Nueva palabra','new-word','','button outline')}</div><div class="words-grid">${rec('word').map(w=>`<details><summary>${esc(w.name)}</summary><p>${esc(w.translation)}</p><small>${esc(w.example)}</small>${btn('Editar','edit-word',`data-id="${w.id}"`,'text-button')}</details>`).join('')||'<p class="muted">Guardá palabras y tocá cada una para revelar su significado.</p>'}</div></section>`;}
function journalView(){const j=rec('journal').find(j=>j.date===dayKey()&&!j.achievement&&!j.workoutPhoto&&!j.englishPractice);return `<section class="journal-intro"><div><p class="eyebrow">UN MOMENTO CON VOS</p><h2>¿Qué te gustaría recordar de hoy?</h2><p>Un pensamiento, una alegría, algo que aprendiste.</p>${btn(icon('NotebookPen')+(j?'Editar mi día':'Escribir sobre mi día'),'journal','','button primary')}</div><span class="journal-flower">${icon('Flower2')}</span></section><div class="journal-grid">${rec('journal').filter(j=>!j.workoutPhoto).sort((a,b)=>b.date.localeCompare(a.date)).map(j=>`<button class="journal-card" data-action="edit-journal" data-id="${j.id}"><small>${prettyDate(j.date)}</small><h3>${j.achievement?'✧ Un logro para recordar':['','😔','😐','🙂','😊','🤩'][j.mood||0]||'Mi día'}</h3><p>${esc(j.text||'Hoy me tomé un momento para registrar cómo me sentía.')}</p></button>`).join('')||empty('Este espacio es tuyo. No hace falta escribir algo perfecto.')}</div>`;}
function projectsView(){return `<div class="section-title"><h2>De a poquito, más cerca</h2>${btn(icon('Plus')+'Nuevo proyecto','new-project','','button primary')}</div><div class="project-grid">${rec('project').map(p=>{const tasks=rec('task').filter(t=>t.projectId===p.id),done=tasks.filter(t=>t.done).length;return `<article class="panel"><span class="habit-icon">${icon('Flag')}</span><h2>${esc(p.name)}</h2><p>${esc(p.note)}</p><progress max="${tasks.length||1}" value="${done}"></progress><small>${done} de ${tasks.length} tareas completadas</small><div class="button-row">${btn('Editar','edit-project',`data-id="${p.id}"`,'text-button')}${btn(icon('Plus')+'Agregar tarea','project-task',`data-id="${p.id}"`,'text-button')}</div>${taskList(tasks)}</article>`;}).join('')||empty('Un proyecto grande empieza con un primer paso.','new-project','Crear proyecto')}</div>`;}
function progressView(){const today=dayKey(),week=weekKeys(today),logs=rec('log').filter(l=>week.includes(l.date)&&l.status==='done'),minutes=rec('reading').filter(r=>week.includes(r.date)).reduce((n,r)=>n+Number(r.minutes),0);return `<div class="stat-grid"><article class="panel"><span>${icon('CheckCheck')} ESTA SEMANA</span><strong>${logs.length}</strong><p>hábitos completados</p></article><article class="panel"><span>${icon('BookOpen')} TIEMPO PARA LEER</span><strong>${minutes}<small> min</small></strong><p>de lectura registrada esta semana</p></article><article class="panel"><span>${icon('Target')} TUS LIBROS</span><strong>${rec('book').filter(b=>b.status==='finished').length}</strong><p>historias terminadas</p></article></div><section class="panel"><div class="section-title"><h2>Tu semana, paso a paso</h2><p>Hábitos completados</p></div><div class="week-chart">${week.map(d=>{const st=dayStats(rec('habit'),rec('log'),d);return `<div><b>${st.done}</b><div class="bar-track"><span style="height:${st.percent}%"></span></div><small>${prettyDate(d,{weekday:'short'})}</small></div>`;}).join('')}</div></section><section class="panel"><h2>Pequeñas constancias</h2><p class="muted">Las pausas registradas y los días no programados no cortan tu racha.</p>${rec('habit').filter(h=>!h.archived).map(h=>`<div class="streak-row">${icon(h.icon)}<span>${esc(h.name)}</span><b>${streak(h,rec('log'),today)} días</b></div>`).join('')}</section><section class="panel"><h2>Las últimas cuatro semanas</h2><div class="heatmap">${Array.from({length:28},(_,i)=>{const d=addDays(today,i-27),st=dayStats(rec('habit'),rec('log'),d);return `<button style="--level:${st.percent/100}" data-action="date" data-date="${d}" title="${d}: ${st.done} completados"><small>${parseDay(d).getDate()}</small></button>`;}).join('')}</div></section>`;}
function showModal(title,body,onSubmit){modal.innerHTML=`<div class="modal-heading"><h2>${title}</h2>${btn(icon('X'),'close','aria-label="Cerrar"','icon-button')}</div>${body}`;if(!modal.open)modal.showModal();paintIcons();const f=modal.querySelector('form');if(f)f.onsubmit=async e=>{e.preventDefault();const submit=f.querySelector('[type="submit"]');if(submit)submit.disabled=true;try{await onSubmit(new FormData(f));}catch(error){toast('No se pudo guardar: '+error.message);}finally{if(submit)submit.disabled=false;}};}
const input=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const textarea=(label,name,value='')=>`<label>${label}<textarea name="${name}" rows="3" maxlength="10000">${esc(value)}</textarea></label>`;
const select=(label,name,options,value)=>`<label>${label}<select name="${name}">${options.map(([id,label])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`;
const areaSelect=v=>select('Área','area',areas().map(a=>[a.id,a.name]),v||areaFilter||'personal');
const formFooter=(kind,id)=>`<div class="modal-footer">${id?btn(icon('Trash2')+'Eliminar','delete',`data-kind="${kind}" data-id="${id}"`,'text-button danger'):''}<button type="button" class="button outline" data-action="close">Cancelar</button><button type="submit" class="button primary">Guardar ${icon('Check')}</button></div>`;
function editor(kind,id='',preset={}){const r={...(id?get(kind,id):{}),...preset};let fields='';
 if(kind==='habit')fields=`${input('Nombre de tu hábito','name',r.name,'text','required maxlength="100" placeholder="Ej.: Leer un ratito"')}<div class="form-grid">${areaSelect(r.area)}<fieldset class="icon-picker"><legend>Elegí un ícono</legend>${ICONS.map(i=>`<label title="${i}"><input type="radio" name="icon" value="${i}" ${(r.icon||'Sun')===i?'checked':''}><span>${icon(i)}</span></label>`).join('')}</fieldset>${select('Momento del día','period',[['mañana','Mañana'],['tarde','Tarde'],['noche','Noche']],r.period||'mañana')}${select('Cómo lo registrás','type',[['check','Un toque: hecho'],['time','Tiempo en minutos'],['quantity','Cantidad']],r.type||'check')}<div data-target-fields ${(!r.type||r.type==='check')?'hidden':''}>${input('Meta diaria','target',r.target||1,'number','min="0.01" step="0.01" max="100000" required')}${input('Unidad','unit',r.unit||'veces','text','required maxlength="30"')}</div></div><fieldset><legend>Días de la semana</legend><div class="button-row">${[["0,1,2,3,4,5,6","Todos los días"],["1,2,3,4,5","Lunes a viernes"],["0,6","Fines de semana"]].map(([days,label])=>`<button type="button" class="chip" data-action="day-shortcut" data-days="${days}">${label}</button>`).join('')}</div><div class="day-picker">${['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'].map((d,i)=>`<label><input type="checkbox" name="days" value="${i}" ${(r.days||[0,1,2,3,4,5,6]).includes(i)?'checked':''}><span>${d}</span></label>`).join('')}</div></fieldset><label class="check-label"><input type="checkbox" name="essential" ${r.essential?'checked':''}>Es importante para mí (lo veo incluso en días tranquilos)</label>${id?'<label class="check-label"><input type="checkbox" name="archived" '+(r.archived?'checked':'')+'>Pausar este hábito (conserva el historial)</label>':''}${input('Hora sugerida','suggestedTime',r.suggestedTime||'','time')}${select('Recordatorio','reminderMinutes',[['','Sin aviso'],['0','A la hora'],['15','15 minutos antes'],['60','Una hora antes']],r.reminderMinutes??'')}${input('Color de la ficha','color',r.color||area(r.area).color,'color')}<input type="hidden" name="order" value="${r.order??rec('habit').length}">${textarea('Una nota para vos','note',r.note)}`;
 if(kind==='area')fields=`${input('Nombre','name',r.name,'text','required maxlength="60"')}${select('Ícono','icon',ICONS.map(i=>[i,i]),r.icon||'Leaf')}${input('Color','color',r.color||'#738d70','color')}`;
 if(kind==='event')fields=`${input('¿Qué tenés planeado?','name',r.name,'text','required maxlength="150"')}${areaSelect(r.area)}<div class="form-grid">${input('Fecha inicial','date',r.date||date,'date','required')}${select('Repetir','repeat',[['none','No se repite'],['daily','Cada día'],['weekly','Cada semana'],['monthly','Cada mes'],['yearly','Cada año']],r.repeat||'none')}${input('Hora (vacía = todo el día)','time',r.time,'time')}${input('Hora de finalización','end',r.end,'time')}${input('Repetir hasta (opcional)','until',r.until,'date')}</div>${select('Recordatorio','reminderMinutes',[['','Sin aviso'],['0','A la hora'],['15','15 minutos antes'],['60','Una hora antes'],['1440','Un día antes']],r.reminderMinutes??'')}${input('Lugar o dirección','location',r.location,'text','maxlength="200"')}${textarea('Notas y cosas para llevar','note',r.note)}${id&&r.repeat!=='none'?'<p class="notice">Desde el calendario podés elegir editar toda la serie o solamente un día.</p>':''}<p class="muted small">Los eventos aparecen en tu agenda. Los avisos necesitan activación en Ajustes y configuración del servidor.</p>`;
 if(kind==='task')fields=`${input('¿Qué querés hacer?','name',r.name,'text','required maxlength="150"')}${areaSelect(r.area)}<div class="form-grid">${input('Fecha límite (opcional)','due',r.due,'date')}${select('Prioridad','priority',[['media','Media'],['alta','Alta'],['baja','Baja']],r.priority||'media')}</div>${select('Proyecto','projectId',[['','Sin proyecto'],...rec('project').map(p=>[p.id,p.name])],r.projectId||'')}${textarea('Notas','note',r.note)}`;
 if(kind==='project')fields=`${input('Nombre del proyecto','name',r.name,'text','required maxlength="150"')}${areaSelect(r.area)}${input('Fecha objetivo (opcional)','due',r.due,'date')}${textarea('¿Qué querés lograr?','note',r.note)}`;
 if(kind==='book')fields=`${input('Título','title',r.title,'text','required maxlength="200"')}${input('Autor o autora','author',r.author,'text','maxlength="150"')}<div class="form-grid">${select('Estado','status',[['pending','Por leer'],['reading','Leyendo'],['finished','Terminado'],['paused','En pausa']],r.status||'reading')}${input('Color de portada','color',r.color||'#a98b70','color')}${input('Total de páginas','pages',r.pages||1,'number','min="1" max="100000" required')}${input('Página actual','page',r.page||0,'number','min="0" max="100000" required')}</div>${input('Ubicación en tu biblioteca','location',r.location,'text','maxlength="150"')}${input('Prestado a (opcional)','lentTo',r.lentTo,'text','maxlength="100"')}${select('Tu valoración','rating',[[0,'Sin puntuar'],[1,'★'],[2,'★★'],[3,'★★★'],[4,'★★★★'],[5,'★★★★★']],r.rating||0)}${textarea('Tu reseña o apuntes','note',r.note)}`;
 if(kind==='quote')fields=`${textarea('La frase que querés guardar','text',r.text)}${select('Libro','bookId',[['','Sin libro'],...(catalog().allowed?catalog().reading.map(b=>['lib:'+b.id,b.titulo]):rec('book').map(b=>[b.id,b.title]))],r.bookId)}${input('Página (opcional)','page',r.page,'number','min="1"')}${input('Autor (opcional)','author',r.author)}`;
 if(kind==='journal')fields=`${input('Fecha','date',r.date||dayKey(),'date','required')}${!r.achievement?select('¿Cómo te sentiste?','mood',[[1,'😔 Un día difícil'],[2,'😐 Más o menos'],[3,'🙂 Bien'],[4,'😊 Muy bien'],[5,'🤩 Con mucha energía']],r.mood||3):''}${textarea(r.achievement?'¿Qué lograste?':'¿Qué te gustaría recordar?','text',r.text)}`;
 if(kind==='word')fields=`${input('Palabra en inglés','name',r.name,'text','required maxlength="100"')}${input('Traducción','translation',r.translation,'text','required maxlength="200"')}${textarea('Un ejemplo','example',r.example)}`;
 const titles={habit:'Tu hábito',area:'Tu área',event:'Tu evento',task:'Tu pendiente',project:'Tu proyecto',book:'Tu libro',quote:'Palabras para guardar',journal:r.achievement?'También hice esto':'Mi momento del día',word:'Una palabra nueva'};
 showModal((id?'Editar · ':'')+titles[kind],`<form>${fields}${formFooter(kind,id)}</form>`,f=>{const data={...r,...Object.fromEntries(f)};delete data.id;
 if(kind==='habit'){data.days=f.getAll('days').map(Number);if(!data.days.length)throw new Error('Elegí al menos un día.');data.target=Number(data.target);data.order=Number(data.order);data.essential=f.has('essential');data.archived=f.has('archived');data.startDate=r.startDate||dayKey();if(data.type==='time')data.unit='minutos';}
 if(kind==='book'){data.page=Number(data.page);data.pages=Number(data.pages);data.rating=Number(data.rating);if(data.page>data.pages)throw new Error('La página actual no puede superar el total.');if(data.status==='finished'){data.page=data.pages;data.finishedAt=r.finishedAt||dayKey();}}
 if(kind==='event'){if(data.end&&!data.time)throw new Error('Indicá una hora inicial.');if(data.end&&data.end<=data.time)throw new Error('La hora final debe ser posterior a la inicial.');if(data.until&&data.until<data.date)throw new Error('La fecha final no puede ser anterior al inicio.');const overlap=rec('event').some(e=>e.id!==id&&occurs(e,data.date)&&e.time&&data.time&&data.time<(e.end||e.time)&&e.time<(data.end||data.time));if(overlap)toast('Guardado. Atención: coincide con otro evento de ese día.');}
 if(kind==='journal'){data.mood=Number(data.mood)||null;data.at=r.at||new Date().toISOString();}
 if(kind==='quote'&&!data.text.trim())throw new Error('Escribí una frase.');
 if(kind==='area'&&id)data.id=id;
 if(kind==='event'&&r._occurrenceDate){if(data.date!==r._occurrenceDate)throw new Error('Para cambiar de fecha, cancelá este día y creá otro evento.');const base=get('event',id);const override={name:data.name,time:data.time,end:data.end,location:data.location,note:data.note,area:data.area};db.put('event',{...base,exceptions:{...base.exceptions,[r._occurrenceDate]:override}},id);}else db.put(kind,data,id||undefined);modal.close();toast('Guardado. Un pequeño paso más.');});
}
function habitAction(id,d=dayKey()){if(d>dayKey())return toast('Podés registrar actividades de hoy o de días pasados.');const h=get('habit',id);if(!h)return;const logId=`log:${id}:${d}`,l=get('log',logId);if(l?.status==='done'){db.remove(logId);toast('Actividad desmarcada.');return;}if(h.type==='check'){db.put('log',{habitId:id,date:d,status:'done',value:1,at:new Date().toISOString()},logId);toast('¡Un paso más! Bien por vos.');return;}showModal(h.name,`<form><p class="muted">Tu meta es ${h.target} ${esc(h.unit)}. Podés registrar un avance parcial.</p>${input('Cantidad total de hoy','value',l?.value||0,'number','required min="0" max="100000" step="0.1"')}${textarea('Una nota (opcional)','note',l?.note)}${formFooter('log','')}</form>`,f=>{const value=Number(f.get('value'));db.put('log',{habitId:id,date:d,value,note:f.get('note'),status:value>=h.target?'done':'partial',at:new Date().toISOString()},logId);modal.close();toast(value>=h.target?'¡Meta cumplida!':'Avance guardado. Cada poquito suma.');});}
function readingForm(minutes=0,timer=null){const c=catalog(),books=c.allowed?c.reading.map(b=>['lib:'+b.id,b.titulo]):rec('book').map(b=>[b.id,b.title]);const selected=timer?.bookId||currentReading()?.id||'';const progress=c.allowed&&c.canWrite&&c.reading.length?`<div class="form-grid">${input('¿En qué página quedaste? (opcional)','page','','number','min="0" max="100000"')}<label class="check-label" style="align-self:end"><input type="checkbox" name="finish">¡Terminé este libro!</label></div><p class="muted small">La página y el final se guardan también en tu biblioteca.</p>`:'';showModal('Tu momento de lectura',`<form>${select('¿Qué leíste?','bookId',[['','Lectura libre'],...books],selected)}<div class="form-grid">${input('Fecha','date',dayKey(),'date','required')}${input('Minutos de lectura','minutes',minutes||1,'number','required min="1" max="1440"')}</div>${progress}${textarea('Algo para recordar','note','')}${formFooter('reading','')}</form>`,f=>{const bookId=f.get('bookId')||'',lib=catalogBook(bookId),page=f.get('page'),finish=f.get('finish')==='on';if(lib&&page!==null&&page!==''&&lib.paginas&&Number(page)>lib.paginas)throw new Error(`Este libro tiene ${lib.paginas} páginas.`);db.put('reading',{bookId,bookTitle:lib?.titulo||'',date:f.get('date'),note:f.get('note')||'',minutes:Number(f.get('minutes')),at:new Date().toISOString()});if(timer)db.remove('reading-timer');modal.close();toast('Tu tiempo de lectura quedó guardado.');if(lib&&(finish||(page!==null&&page!=='')))recordProgress(bookId,{page:page===''||page===null?null:Number(page),finish,comment:f.get('note')||''}).then(()=>toast(finish?`¡Terminaste «${lib.titulo}»! Qué lindo logro.`:'Tu página quedó guardada en la biblioteca.')).catch(e=>toast('La lectura se guardó, pero no la página: '+e.message));});}
function settingsModal(){const s=settings();showModal('A tu manera',`<form>${input('Tu nombre','name',s.name,'text','maxlength="60"')}<div class="form-grid">${select('Apariencia','theme',[['light','Clara'],['dark','Oscura']],s.theme||'light')}${select('Cómo querés vivir hoy','dayMode',[['habitual','Día habitual'],['tranquilo','Día tranquilo'],['descanso','Descanso']],s.dayMode||'habitual')}</div><label class="check-label"><input type="checkbox" name="large" ${s.large?'checked':''}>Texto más grande</label><label class="check-label"><input type="checkbox" name="quiet" ${s.quiet?'checked':''}>Reducir animaciones</label><label class="check-label"><input type="checkbox" name="quietWork" ${s.quietWork?'checked':''}>Pausar avisos personales durante mis bloques de trabajo</label><p class="muted">${user.id==='demo'?'Estás explorando una demo local. Tus cambios no se sincronizan.':esc(user.email||'Cuenta conectada')}</p>${formFooter('settings','')}</form><hr><div class="settings-actions">${btn('Importar respaldo','extra-import','','button outline')}${btn(icon('Download')+'Exportar mis datos','export','','button outline')}${btn(icon('Trash2')+'Papelera','trash','','button outline')}${btn(icon('RotateCcw')+'Hábitos pausados','archived','','button outline')}${btn(icon('LogOut')+(user.id==='demo'?'Salir de la demo':'Cerrar sesión'),'logout','','button outline')}</div>${notificationsView({btn})}<div class="install-help"><h3>Siempre a mano</h3><p><b>iPhone:</b> abrí la app en Safari, tocá Compartir y “Agregar a inicio”.</p><p><b>Windows:</b> usá la opción de instalar aplicación de Edge o Chrome.</p><p class="muted small">Los recordatorios requieren activar este dispositivo y configurar el envío en el servidor.</p></div>`,f=>{db.put('settings',{...s,name:f.get('name'),theme:f.get('theme'),dayMode:f.get('dayMode'),large:f.has('large'),quiet:f.has('quiet'),quietWork:f.has('quietWork')},'settings');modal.close();toast('Tu espacio, a tu gusto.');});}
function confirmModal(title,message,callback){showModal(title,`<p>${message}</p><div class="modal-footer">${btn('Cancelar','close','','button outline')}<button id="confirm" class="button primary">Confirmar</button></div>`);modal.querySelector('#confirm').onclick=()=>{modal.close();callback();};}
function searchModal(){showModal('Encontrá lo que buscás',`<label>Buscar en tu espacio<input id="global-search" type="search" placeholder="Un libro, una tarea, un hábito…" autofocus></label><div id="search-results"></div>`);modal.querySelector('#global-search').oninput=e=>{const q=e.target.value.trim().toLocaleLowerCase();const kinds=['habit','event','task','project','book','quote','journal','word'];const results=q?kinds.flatMap(kind=>rec(kind).filter(r=>`${r.name||''} ${r.title||''} ${r.text||''} ${r.note||''} ${r.author||''}`.toLocaleLowerCase().includes(q)).map(r=>({kind,...r}))):[];modal.querySelector('#search-results').innerHTML=results.slice(0,30).map(r=>btn(`<strong>${esc(r.name||r.title||r.text?.slice(0,100))}</strong><small>${({habit:'Hábito',event:'Evento',task:'Tarea',project:'Proyecto',book:'Libro',quote:'Cita',journal:'Diario',word:'Vocabulario'})[r.kind]}</small>`,'search-result',`data-kind="${r.kind}" data-id="${r.id}"`,'search-result')).join('')||'<p class="muted">'+(q?'No encontramos coincidencias.':'Escribí para buscar.')+'</p>';};}
async function action(a,el){if(await notificationsAction(a,{toast}))return;if(await extrasAction(a,el,{showModal,input,btn,esc,modal,toast}))return;if(a==='calendar-mode'){window.calendarMode=el.dataset.mode;render();return;}if(a==='week-step'){date=addDays(date,Number(el.dataset.step));month=date.slice(0,7);render();return;}if(a==='event-options'){const e=get('event',el.dataset.id),d=el.dataset.date;if(!e.repeat||e.repeat==='none'){editor('event',e.id);return;}showModal('Evento repetido',`<p>Elegí qué querés modificar.</p>${btn('Editar toda la serie','edit-event',`data-id="${e.id}"`,'button outline')}${btn('Editar solo este día','edit-occurrence',`data-id="${e.id}" data-date="${d}"`,'button outline')}${btn('Cancelar solo este día','cancel-occurrence',`data-id="${e.id}" data-date="${d}"`,'button outline')}`);return;}if(a==='edit-occurrence'){const e=get('event',el.dataset.id);editor('event',e.id,{...eventOnDate(e,el.dataset.date),date:el.dataset.date,_occurrenceDate:el.dataset.date});return;}if(a==='cancel-occurrence'){const e=get('event',el.dataset.id);db.put('event',{...e,exceptions:{...e.exceptions,[el.dataset.date]:{cancelled:true}}},e.id);modal.close();toast('Cancelado solo para esa fecha.');return;}if(await planningAction(a,el,{showModal,input,textarea,select,modal,toast}))return;if(await wellbeingAction(a,el,{showModal,input,textarea,btn,esc,toast,modal,render}))return;if(a==='day-shortcut'){const days=el.dataset.days.split(',');modal.querySelectorAll('[name=days]').forEach(x=>x.checked=days.includes(x.value));return;}const id=el.dataset.id,d=el.dataset.date||dayKey();if(a==='close'){modal.close();return;}if(['signup','login','reset'].includes(a)){authMode=a;renderAuth();return;}if(a==='demo'){await enter({id:'demo'});return;}if(a==='nav'){view=el.dataset.view;modal.close();render();window.scrollTo(0,0);return;}if(a==='area'){view='areas';areaFilter=id||'';render();return;}if(a==='space-tab'){tab=el.dataset.tab;render();return;}if(a==='progress'||a==='library'){view='space';tab=a==='progress'?'progreso':'biblioteca';render();return;}if(a==='period'){window.periodFilter=el.dataset.period;render();return;}if(a==='settings'){settingsModal();return;}if(a==='sync'){await db.sync();if(db.info().status==='error')toast('No se pudo conectar. Tus cambios siguen guardados en este equipo.');return;}
 if(a==='logout'){const finish=async()=>{if(user.id!=='demo'){const {error}=await db.supabase.auth.signOut({scope:'local'});if(error){toast(error.message);return;}}db.closeStore();closeCatalog();user=null;ready=false;modal.close();render();};if(db.info().pending)confirmModal('Hay cambios pendientes','Los cambios quedan en este navegador. Volvé a entrar en este equipo para sincronizarlos. ¿Cerrar sesión?',finish);else await finish();return;}
 if(a==='create'){showModal('¿Qué querés agregar?',`<div class="create-options">${[['habit','Sun','Un hábito','Algo que querés repetir'],['event','CalendarDays','Un evento','Un plan con fecha'],['task','CheckCheck','Una tarea','Un pendiente para resolver'],['project','Flag','Un proyecto','Algo grande, paso a paso'],['book','BookOpen','Un libro','Tu próxima lectura']].map(([k,i,t,s])=>btn(icon(i)+`<div><strong>${t}</strong><small>${s}</small></div>`,'new-'+k,'','create-option')).join('')}</div>`);return;}
 if(a.startsWith('new-')){editor(a.slice(4));return;}if(a.startsWith('edit-')){editor(a.slice(5),id);return;}if(a==='search-result'){editor(el.dataset.kind,id);return;}
 if(a==='habit-action'){habitAction(id,d);return;}if(a==='skip'){if(d>dayKey())return toast('Las pausas se registran hoy o en días pasados.');db.put('log',{habitId:id,date:d,status:'skip',at:new Date().toISOString(),value:0},`log:${id}:${d}`);toast('Pausa registrada. Descansar también cuenta.');return;}
 if(a==='date'){date=d;month=d.slice(0,7);view='calendar';render();return;}if(a==='month'){const dt=parseDay(month+'-01');dt.setMonth(dt.getMonth()+Number(el.dataset.step));month=dayKey(dt).slice(0,7);render();return;}if(a==='calendar-today'){date=dayKey();month=date.slice(0,7);render();return;}
 if(a==='event-done'){if(d>dayKey())return toast('Podés completar eventos de hoy o anteriores.');const key=`event:${id}:${d}`;if(get('eventLog',key))db.remove(key);else db.put('eventLog',{eventId:id,date:d,at:new Date().toISOString()},key);return;}
 if(a==='task-done'){const t=get('task',id);db.put('task',{...t,done:!t.done},id);return;}if(a==='project-task'){editor('task','',{projectId:id,area:get('project',id)?.area});return;}
 if(a==='timer-start'){const book=currentReading();db.put('timer',{startedAt:Date.now(),elapsed:0,running:true,bookId:book?.id||''},'reading-timer');toast('Tu momento de lectura empezó.');return;}if(a==='timer-toggle'){const t=get('timer','reading-timer');if(!t)return;db.put('timer',{...t,elapsed:t.running?(t.elapsed||0)+Date.now()-t.startedAt:t.elapsed,running:!t.running,startedAt:Date.now()},t.id);return;}if(a==='timer-stop'){const t=get('timer','reading-timer');if(!t)return;const seconds=elapsed(t);db.put('timer',{...t,elapsed:seconds*1000,running:false},t.id);readingForm(Math.max(1,Math.round(seconds/60)),t);return;}if(a==='manual-reading'){readingForm();return;}
 if(a==='mood'){const existing=rec('journal').find(j=>j.date===dayKey()&&!j.achievement&&!j.workoutPhoto&&!j.englishPractice);editor('journal',existing?.id||'',{date:dayKey(),mood:Number(el.dataset.mood)});return;}if(a==='journal'){const j=rec('journal').find(j=>j.date===dayKey()&&!j.achievement&&!j.workoutPhoto&&!j.englishPractice);editor('journal',j?.id||'');return;}if(a==='achievement'){editor('journal','',{achievement:true});return;}
 if(a==='delete'){if(el.dataset.kind==='area'&&['habit','event','task','project'].some(k=>rec(k).some(r=>r.area===id)))return toast('Primero mové a otra área las actividades que la usan.');confirmModal('¿Mover a la papelera?','Podés recuperarlo después desde Ajustes → Papelera.',()=>{db.remove(id);toast('Movido a la papelera.');});return;}
 if(a==='trash'){showModal('Tu papelera',`<div>${db.trash().map(r=>`<div class="trash-row"><span>${esc(r.data.name||r.data.title||r.data.text||'Registro')}</span>${btn('Restaurar','restore',`data-id="${r.id}"`,'button outline')}</div>`).join('')||'<p class="muted">No hay elementos en la papelera.</p>'}</div>`);return;}if(a==='restore'){db.restore(id);modal.close();toast('Recuperado.');return;}
 if(a==='archived'){showModal('Hábitos pausados',rec('habit').filter(h=>h.archived).map(h=>btn(esc(h.name),'edit-habit',`data-id="${h.id}"`,'search-result')).join('')||'<p class="muted">No tenés hábitos pausados.</p>');return;}
 if(a==='export'){const data=JSON.stringify(db.exportData(),null,2),url=URL.createObjectURL(new Blob([data],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=`habits-${dayKey()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exportación preparada.');return;}if(a==='search'){searchModal();return;}
 if(a==='conflicts'){showModal('Cambios de tus dispositivos',db.info().conflicts.map(c=>`<section class="conflict"><h3>${esc(c.local.data.name||c.local.data.title||'Registro')}</h3><p>Ambos dispositivos editaron este registro. Elegí cuál conservar.</p><details><summary>Ver ambas versiones</summary><h4>Este equipo</h4><pre>${esc(JSON.stringify(c.local.data,null,2))}</pre><h4>Otro dispositivo</h4><pre>${esc(JSON.stringify(c.remote?.data||{},null,2))}</pre></details><div class="button-row">${btn('Conservar este equipo','resolve',`data-id="${c.id}" data-local="true"`,'button outline')}${btn('Usar el otro dispositivo','resolve',`data-id="${c.id}" data-local="false"`,'button primary')}</div></section>`).join(''));return;}if(a==='resolve'){db.resolveConflict(id,el.dataset.local==='true');modal.close();toast('Cambio resuelto.');return;}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();Promise.resolve(action(el.dataset.action,el)).catch(err=>{console.error(err);toast('No se pudo completar: '+err.message);});});
document.addEventListener('change',e=>{if(e.target.name==='type'&&modal.querySelector('[data-target-fields]')){modal.querySelector('[data-target-fields]').hidden=e.target.value==='check';if(e.target.value==='time')modal.querySelector('[name=unit]').value='minutos';}if(e.target.id==='day-mode')db.put('settings',{...settings(),dayMode:e.target.value,dayModeDate:dayKey()},'settings');});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
let lastDay=dayKey();function tick(){document.querySelectorAll('[data-clock]').forEach(e=>e.textContent=new Date().toLocaleTimeString('es-PY',{hour:'2-digit',minute:'2-digit'}));const t=get('timer','reading-timer');document.querySelectorAll('[data-timer]').forEach(e=>e.textContent=t?fmtDuration(elapsed(t)):'00:00');if(lastDay!==dayKey()){lastDay=dayKey();if(user)render();}}
setInterval(tick,1000);
renderAuth();
if(db.supabase){db.supabase.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){recovery=true;renderAuth();}if(session?.user){setTimeout(()=>enter(session.user),0);}else if(user&&user.id!=='demo'){db.closeStore();user=null;ready=false;render();}});}
if('serviceWorker' in navigator&&import.meta.env.PROD)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));

let draggedHabit=null;
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-habit-id]');if(card){draggedHabit=card.dataset.habitId;e.dataTransfer.setData('text/plain',draggedHabit);}});
document.addEventListener('dragover',e=>{if(draggedHabit&&e.target.closest('[data-habit-id]'))e.preventDefault();});
document.addEventListener('drop',e=>{const card=e.target.closest('[data-habit-id]');if(!draggedHabit||!card)return;e.preventDefault();const hs=rec('habit').sort((a,b)=>(a.order||0)-(b.order||0)),from=hs.findIndex(h=>h.id===draggedHabit),to=hs.findIndex(h=>h.id===card.dataset.habitId);if(from>=0&&to>=0){hs.splice(to,0,hs.splice(from,1)[0]);hs.forEach((h,i)=>{if(h.order!==i)db.put('habit',{...h,order:i},h.id);});}draggedHabit=null;});
document.addEventListener('dragend',()=>draggedHabit=null);
